import { placeOrder, orderLine, fetchOrderLine } from "/workspace/dist/orders.js";
import { describeStatus } from "/workspace/dist/status.js";
import { trackingSummary } from "/workspace/dist/shipments.js";

// --- a fake transport that records the specs it is handed ---
const seen = [];
const order = { createdAt: "2026-01-02T03:04:05Z", id: "o-1", status: "pending", total: 900 };
const shipments = [
  { carrier: "UPS", trackingNumber: "1Z999" },
  { carrier: "DHL", trackingNumber: "JD00", deliveredAt: "2026-01-09T00:00:00Z" },
];
const transport = {
  async request(spec) {
    seen.push(spec);
    if (spec.method === "POST") return order;
    if (spec.path.endsWith("/shipments")) return shipments;
    return order;
  },
};

// idempotency key defaulted per README
const placed = await placeOrder(transport, "c-77", 900);
console.log("POST spec body:", JSON.stringify(seen[0].body));
console.log("placed id:", placed.id);

// idempotency key supplied by caller is used as is
await placeOrder(transport, "c-77", 900, "my-key");
console.log("explicit key body:", JSON.stringify(seen[1].body));

// status labels, one per member of OrderStatus
for (const s of ["pending", "shipped", "cancelled", "refunded"]) {
  console.log(`label ${s} ->`, describeStatus(s));
}

// tracking line: order id, ": ", tracking numbers joined by ", "
console.log("tracking line:", await trackingSummary(transport, "o-1"));

// no shipments -> order id followed by ": none"
const emptyTransport = {
  async request() { return []; },
};
console.log("empty tracking line:", await trackingSummary(emptyTransport, "o-2"));

// order line uses the current Order shape
console.log("order line:", await fetchOrderLine(transport, "o-1"), "|", orderLine(order));
EOF
